        self.assertEqual(team_capacity(TEAM, S, E), 1000 + 250 + 720)
        self.assertEqual(team_capacity(TEAM, S, E, {D(2025, 3, 7)}), 900 + 200 + 640)
        self.assertEqual(team_capacity({}, S, E), 0)

