        self.assertEqual(sprint_points(team, S, 10), 0)
        team = {"x": {"allocation": 100}}
        self.assertEqual(sprint_points(team, D(2025, 3, 8), 10), 10)
        self.assertEqual(sprint_points(team, D(2025, 3, 10), 10), 10)

